    91	/**
    92	 * Extract `<div class="article-prose"> ... </div>` region with boundary offsets.
    93	 *
    94	 * @return array<string,mixed>
    95	 */
    96	function extract_prose_region(string $html): array
    97	{
    98	  if (!preg_match('/<div\b[^>]*class=(["\'])(?:(?!\1).)*\barticle-prose\b(?:(?!\1).)*\1[^>]*>/is', $html, $match, PREG_OFFSET_CAPTURE)) {
    99	    return [
   100	      'ok' => false,
   101	      'code' => 'missing_prose_region',
   102	      'message' => 'Không tìm thấy khối .article-prose.',
   103	    ];
   104	  }
   105	
   106	  $openTag = (string) $match[0][0];
   107	  $openOffset = (int) $match[0][1];
   108	  $openEnd = $openOffset + strlen($openTag);
   109	
   110	  $closeOffset = find_matching_div_close_offset($html, $openOffset);
   111	  if ($closeOffset === null) {
   112	    return [
   113	      'ok' => false,
   114	      'code' => 'unbalanced_prose_div',
   115	      'message' => 'Không xác định được thẻ đóng của .article-prose.',
   116	    ];
   117	  }
   118	
   119	  $closeTag = '</div>';
   120	  $inner = substr($html, $openEnd, $closeOffset - $openEnd);
   121	  if ($inner === false) {
   122	    $inner = '';
   123	  }
   124	
   125	  return [
   126	    'ok' => true,
   127	    'start' => $openOffset,
   128	    'open_tag_end' => $openEnd,
   129	    'close_tag_start' => $closeOffset,
   130	    'end' => $closeOffset + strlen($closeTag),
   131	    'open_tag' => $openTag,
   132	    'close_tag' => $closeTag,
   133	    'inner' => $inner,
   134	    'inner_length' => strlen($inner),
   135	  ];
   136	}
   137	
   138	/**
   139	 * Find matching closing `</div>` offset for div opened at $openOffset.
   140	 */
   141	function find_matching_div_close_offset(string $html, int $openOffset): ?int
   142	{
   143	  $tail = substr($html, $openOffset);
   144	  if ($tail === false || $tail === '') {
   145	    return null;
   146	  }
   147	
   148	  if (!preg_match_all('/<\/?div\b[^>]*>/i', $tail, $tokens, PREG_OFFSET_CAPTURE)) {
   149	    return null;
   150	  }
   151	
   152	  $depth = 0;
   153	  $started = false;
   154	  foreach ($tokens[0] as $entry) {
   155	    $token = strtolower((string) $entry[0]);
   156	    $offset = $openOffset + (int) $entry[1];
   157	    $isClose = str_starts_with($token, '</div');
   158	
   159	    if (!$started) {
   160	      if ($offset !== $openOffset) {
   161	        continue;
   162	      }
   163	      $started = true;
   164	      $depth = 1;
   165	      continue;
   166	    }
   167	
   168	    if ($isClose) {
   169	      $depth--;
   170	      if ($depth === 0) {
   171	        return $offset;
   172	      }
   173	      continue;
   174	    }
   175	
   176	    $depth++;
   177	  }
   178	
   179	  return null;
   180	}
