   242	/**
   243	 * Build parser audit report for all indexed articles.
   244	 *
   245	 * @return array<string,mixed>
   246	 */
   247	function run_parser_audit(bool $force = false): array
   248	{
   249	  sync_articles_index(false);
   250	  $cache = read_articles_index_cache();
   251	  $items = is_array($cache['items']) ? $cache['items'] : [];
   252	
   253	  $sourceMTime = file_exists(ADMIN_ARTICLES_SOURCE_PATH) ? (int) filemtime(ADMIN_ARTICLES_SOURCE_PATH) : 0;
   254	  $existing = read_parser_audit_cache();
   255	  $existingMTime = (int) ($existing['meta']['source_mtime'] ?? 0);
   256	
   257	  if (!$force && $existingMTime === $sourceMTime && isset($existing['meta']['safe_count'])) {
   258	    return $existing;
   259	  }
   260	
   261	  $safeCount = 0;
   262	  $fails = [];
   263	  foreach ($items as $article) {
   264	    if (!is_array($article)) {
   265	      continue;
   266	    }
   267	    $path = resolve_article_file_path($article);
   268	    $parsed = parse_article_file($path);
   269	    if (!empty($parsed['ok'])) {
   270	      $safeCount++;
   271	      continue;
   272	    }
   273	    $fails[] = [
   274	      'id' => (string) ($article['id'] ?? ''),
   275	      'href' => (string) ($article['href'] ?? ''),
   276	      'path' => $path,
   277	      'code' => (string) ($parsed['code'] ?? 'unknown'),
   278	      'message' => (string) ($parsed['message'] ?? ''),
   279	    ];
   280	  }
   281	
   282	  $total = count($items);
   283	  $rate = $total > 0 ? round(($safeCount / $total) * 100, 2) : 0.0;
   284	  $report = [
   285	    'meta' => [
   286	      'generated_at' => date('c'),
   287	      'source_mtime' => $sourceMTime,
   288	      'total_count' => $total,
   289	      'safe_count' => $safeCount,
   290	      'fail_count' => count($fails),
   291	      'safe_rate_percent' => $rate,
   292	    ],
   293	    'fails' => $fails,
   294	  ];
   295	
   296	  write_parser_audit_cache($report);
   297	  return $report;
   298	}
