    63	    ];
    64	  }
    65	
    66	  $items = [];
    67	  foreach ($decoded as $item) {
    68	    if (!is_array($item)) {
    69	      continue;
    70	    }
    71	    $normalized = normalize_article_index_item($item);
    72	    if ($normalized !== null) {
    73	      $items[] = $normalized;
    74	    }
    75	  }
    76	
    77	  $cachePayload = [
    78	    'meta' => [
    79	      'source_path' => ADMIN_ARTICLES_SOURCE_PATH,
