   369	/**
   370	 * Rollback latest publish for one article.
   371	 *
   372	 * @param array<string,mixed> $article
   373	 * @param array<string,mixed>|null $actor
   374	 * @return array<string,mixed>
   375	 */
   376	function rollback_latest_publish(array $article, ?array $actor = null): array
   377	{
   378	  $articleId = trim((string) ($article['id'] ?? ''));
   379	  if ($articleId === '') {
   380	    return [
   381	      'ok' => false,
   382	      'code' => 'missing_article_id',
   383	      'message' => 'Thiếu article id để rollback.',
   384	    ];
   385	  }
   386	
   387	  $latest = find_latest_publish_record($articleId);
   388	  if ($latest === null) {
   389	    return [
   390	      'ok' => false,
   391	      'code' => 'no_publish_record',
   392	      'message' => 'Chưa có publish record để rollback.',
   393	    ];
   394	  }
   395	
   396	  $targetPath = (string) ($latest['target_path'] ?? '');
   397	  $backupPath = (string) ($latest['backup_path'] ?? '');
   398	  if ($targetPath === '' || $backupPath === '' || !file_exists($backupPath)) {
   399	    return [
   400	      'ok' => false,
   401	      'code' => 'missing_backup',
   402	      'message' => 'Không tìm thấy backup để rollback.',
   403	    ];
   404	  }
   405	
   406	  if (!is_writable(dirname($targetPath)) || !is_writable($targetPath)) {
   407	    return [
   408	      'ok' => false,
   409	      'code' => 'target_not_writable',
   410	      'message' => 'File đích không có quyền ghi để rollback.',
   411	    ];
   412	  }
   413	
   414	  // Backup current target before restoring
   415	  $rollbackBackupPath = build_backup_file_path($articleId . '-rollback-src');
   416	  if (!copy($targetPath, $rollbackBackupPath)) {
   417	    return [
   418	      'ok' => false,
   419	      'code' => 'rollback_backup_failed',
   420	      'message' => 'Không tạo được backup trạng thái hiện tại trước rollback.',
   421	    ];
   422	  }
   423	
   424	  if (!copy($backupPath, $targetPath)) {
   425	    return [
   426	      'ok' => false,
   427	      'code' => 'rollback_copy_failed',
   428	      'message' => 'Rollback thất bại khi restore backup.',
   429	    ];
   430	  }
   431	
   432	  $restoredHtml = file_get_contents($targetPath);
   433	  $restoredHash = $restoredHtml !== false ? hash('sha256', $restoredHtml) : '';
   434	
   435	  $record = [
   436	    'id' => 'rb-' . date('YmdHis') . '-' . substr(md5($articleId . microtime(true)), 0, 8),
   437	    'event' => 'rollback',
   438	    'article_id' => $articleId,
   439	    'target_path' => $targetPath,
   440	    'restored_from' => $backupPath,
   441	    'current_backup_before_restore' => $rollbackBackupPath,
   442	    'rolled_back_at' => date('c'),
   443	    'restored_hash' => $restoredHash,
   444	    'actor' => [
   445	      'user_id' => (string) (($actor['user_id'] ?? '') ?: ''),
   446	      'username' => (string) (($actor['username'] ?? '') ?: ''),
   447	      'display_name' => (string) (($actor['display_name'] ?? '') ?: ''),
   448	      'role' => (string) (($actor['role'] ?? '') ?: ''),
   449	    ],
   450	    'source_publish_id' => (string) ($latest['id'] ?? ''),
   451	  ];
   452	  append_publish_record($record);
   453	
   454	  append_audit_log([
   455	    'event' => 'article.rollback.success',
   456	    'article_id' => $articleId,
   457	    'username' => (string) (($actor['username'] ?? '') ?: ''),
   458	    'role' => (string) (($actor['role'] ?? '') ?: ''),
   459	    'restored_from' => $backupPath,
   460	  ]);
   461	
   462	  return [
   463	    'ok' => true,
   464	    'code' => 'ok',
   465	    'message' => 'Rollback thành công.',
   466	    'record' => $record,
   467	  ];
   468	}
